9	 *
10	 * A streak ending YESTERDAY still counts. Anchoring strictly on today would
11	 * show every user a zero every morning until they dressed, which reads as
12	 * "you lost your streak" rather than "the day is young".
13	 *
14	 * Counting always starts at today even when the diary is showing an older
15	 * month — a streak that changed as you paged backwards would be measuring the
16	 * view rather than the habit.
17	 *
18	 * Dates are UTC-shifted only for arithmetic; the values themselves are the
19	 * user's local date keys, so no timezone conversion happens here.
20	 */
21	export function currentStreak(dates: string[], today: string): number {
22	  const set = new Set(dates);
23	  let cursor = set.has(today) ? today : shiftDay(today, -1);
24	  if (!set.has(cursor)) return 0;
25	
26	  let n = 0;
27	  while (set.has(cursor)) {
28	    n++;
29	    cursor = shiftDay(cursor, -1);
30	  }
31	  return n;
32	}
