function shiftDay(date: string, delta: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + delta);
  return d.toISOString().slice(0, 10);
}

/**
 * Consecutive days with at least one wear, counting back from today.
 *
 * A streak ending YESTERDAY still counts. Anchoring strictly on today would
 * show every user a zero every morning until they dressed, which reads as
 * "you lost your streak" rather than "the day is young".
 *
 * Counting always starts at today even when the diary is showing an older
 * month — a streak that changed as you paged backwards would be measuring the
 * view rather than the habit.
 *
 * Dates are UTC-shifted only for arithmetic; the values themselves are the
 * user's local date keys, so no timezone conversion happens here.
 */
export function currentStreak(dates: string[], today: string): number {
  const set = new Set(dates);
  let cursor = set.has(today) ? today : shiftDay(today, -1);
  if (!set.has(cursor)) return 0;

  let n = 0;
  while (set.has(cursor)) {
    n++;
    cursor = shiftDay(cursor, -1);
  }
  return n;
}

export type Tier = "free" | "pro";

/** The three things that spend a model request. See docs/MONETISATION.md §2. */
export type GenerationKind = "drop" | "regenerate" | "styled";

export type Entitlements = {
  tier: Tier;
  /**
   * Rerolls per DAY, across all occasions. null = unlimited.
   *
   * Global rather than per-occasion (user decision, 2026-08-05). Most people
   * care about one occasion on a given day, so a per-occasion allowance is
   * strictest exactly where attention goes and generous where nobody is
   * looking: you could be refused a second Work reroll while holding an unused
   * Evening one you never wanted.
   *
   * The usual objection to a global pool — that it can block an occasion you
   * have not opened yet — does not apply here, because a drop is free on every
   * tier. Tapping a new occasion is always a drop, so the pool only ever meters
   * rerolls.
   */
  regeneratesPerDay: number | null;
  /**
   * How many pieces a closet may hold. null = unlimited.
   *
   * Counts UNARCHIVED items only. Archiving is the user's way to make room —
   * there is no delete path in the product, so counting archived pieces would
   * strand a user at the cap with no way out. It also matches what the number
   * claims: an archived piece is not in your closet.
   *
   * 50 is deliberately well clear of the ~20-30 range where combo coverage
   * thins (PR #15 measured a 21-item closet at 21 combos in winter against 48
   * in summer), so the free tier never experiences a starved stylist — it
   * experiences a full one, with a ceiling.
   */
  closetItems: number | null;
  /** "Style an outfit with this" — Pro #2. */
  styledLooks: boolean;
  savedOutfits: number | null;
  /** The Wear Stats SCREEN. The per-item tile on item detail is free. */
  analytics: boolean;
  gapAnalysis: boolean;
  packingMode: boolean;
};

/**
 * The tiers, as data. See docs/MONETISATION.md for the reasoning — in short:
 * meter what costs us money, sell what compounds, and never gate the daily
 * drop, the share card, or the closet.
 *
 * The free ceiling is four occasion drops plus three rerolls = 7 generations a
 * day, about $0.63/month at $0.003 each and nearer $0.20 in realistic use.
 * **The ceiling is the point** — a free tier needs a worst case you can
 * survive, and this one cannot be raised by adding clothes.
 */
export const FREE: Entitlements = {
  tier: "free",
  regeneratesPerDay: 3,
  closetItems: 50,
  styledLooks: false,
  savedOutfits: 10,
  analytics: false,
  gapAnalysis: false,
  packingMode: false,
};

export const PRO: Entitlements = {
  tier: "pro",
  regeneratesPerDay: null,
  closetItems: null,
  styledLooks: true,
  savedOutfits: null,
  analytics: true,
  gapAnalysis: true,
  packingMode: true,
};

// The pure functions live HERE, not in entitlements.ts, so tests can import them
// without dragging in `server-only` (which does not resolve under jsdom).
// entitlements.ts re-exports them for app code.

/** Unknown input resolves to free: capabilities fail CLOSED. */
export function entitlementsFor(tier: unknown): Entitlements {
  return tier === "pro" ? PRO : FREE;
}

export type GenerationCheck = {
  allowed: boolean;
  /** null = unlimited. Only meaningful for a metered kind. */
  remaining: number | null;
  reason?: string;
};

/**
 * May this user spend a model request right now?
 *
 * `regeneratesUsed` is the user's total reroll count for their local today,
 * across every occasion.
 *
 * A drop is never metered on any tier: MONETISATION §1 and Decision 4 both say
 * the daily drop is the product, and rationing it is how nobody discovers the
 * magic. That is also what makes a global reroll pool safe — a user can always
 * open any occasion, so the pool can never strand them.
 */
export function checkGeneration(
  e: Entitlements,
  input: { kind: GenerationKind; regeneratesUsed: number },
): GenerationCheck {
  if (input.kind === "drop") return { allowed: true, remaining: null };

  if (input.kind === "styled") {
    return e.styledLooks
      ? { allowed: true, remaining: null }
      : {
          allowed: false,
          remaining: 0,
          reason: "Building a look around a piece is a Pro feature.",
        };
  }

  if (e.regeneratesPerDay == null) return { allowed: true, remaining: null };
  const remaining = Math.max(0, e.regeneratesPerDay - input.regeneratesUsed);
  return remaining > 0
    ? { allowed: true, remaining }
    : {
        allowed: false,
        remaining: 0,
        reason: `That's your ${e.regeneratesPerDay} rerolls for today. Pro rerolls without limit.`,
      };
}

/**
 * May this user add another piece?
 *
 * `held` is the number of UNARCHIVED pieces already in the closet — archiving
 * is how a free user makes room, since nothing in the product deletes an item.
 */
export function checkCloset(e: Entitlements, held: number): GenerationCheck {
  if (e.closetItems == null) return { allowed: true, remaining: null };
  const remaining = Math.max(0, e.closetItems - held);
  return remaining > 0
    ? { allowed: true, remaining }
    : {
        allowed: false,
        remaining: 0,
        reason: `A free closet holds ${e.closetItems} pieces. Pro is unlimited — or archive something you no longer wear.`,
      };
}

import Link from "next/link";
import type { Tier } from "@/lib/billing/tiers";

export type HubLink = {
  href: string;
  label: string;
  desc: string;
  /** False until the destination exists on `main`. */
  ready: boolean;
};

/**
 * What Pro unlocks, in the order MONETISATION.md §3 lists it.
 *
 * The design's card carries only the one-line pitch, which was enough when this
 * screen was the only place Pro was mentioned. It is now the destination for
 * every gate in the app, so someone arriving here has just been refused
 * something and needs to see what they would actually get.
 */
const PRO_BENEFITS = [
  "Unlimited rerolls, any occasion",
  "Build a look around any piece",
  "An unlimited closet",
  "Packing mode for trips",
  "Cost-per-wear analytics",
  "Gap analysis — what to buy next",
  "Unlimited saved outfits",
];

function StatCell({ value, label }: { value: string; label: string }) {
  return (
    <div className="flex-1 px-[6px] py-4 text-center">
      <div className="font-serif text-[24px] text-foreground">{value}</div>
      <div className="mt-[5px] text-[10px] uppercase tracking-[0.1em] text-muted-dim">{label}</div>
    </div>
  );
}

function LinkRow({ link }: { link: HubLink }) {
  const body = (
    <>
      <div className="size-[38px] shrink-0 rounded-[10px] bg-[#201b18]" aria-hidden="true" />
      <div className="min-w-0 flex-1">
        <div className="text-[15px] text-foreground">{link.label}</div>
        <div className="mt-[2px] text-[12px] text-muted-foreground">{link.desc}</div>
      </div>
      {link.ready ? (
        <span className="text-[20px] text-muted-dim" aria-hidden="true">
          ›
        </span>
      ) : (
        <span className="text-[10px] uppercase tracking-[0.14em] text-muted-dim">Soon</span>
      )}
    </>
  );

  const shell =
    "flex items-center gap-[14px] rounded-[14px] bg-surface-1 px-4 py-[15px] shadow-[inset_0_0_0_1px_var(--hairline-2)]";

  // An unready row is NOT a link. Two of the four bottom tabs used to 404 for
  // exactly this reason (BUGS.md #5); it should not repeat one level down.
  return link.ready ? (
    <Link href={link.href} className={shell}>
      {body}
    </Link>
  ) : (
    <div className={`${shell} opacity-60`}>{body}</div>
  );
}

/**
 * The profile hub (`Fitcheck.dc.html:659-702`).
 *
 * Presentational: every count is computed by the route.
 */
export function ProfileHub({
  name,
  handle,
  initials,
  archetype,
  palette,
  tier,
  stats,
  links,
  children,
}: {
  name: string;
  handle: string;
  initials: string;
  archetype: string | null;
  palette: string[];
  tier: Tier;
  /** `outfits` is looks WORN, not looks generated — see the route. */
  stats: { pieces: number; outfits: number; streak: number };
  links: HubLink[];
  /** Sign-out, until Settings owns it. */
  children?: React.ReactNode;
}) {
  const isPro = tier === "pro";

  return (
    <div className="flex-1 overflow-y-auto px-[22px] pb-[120px] screen-top">
      <div className="flex items-center gap-[14px]">
        <div className="grid size-[62px] shrink-0 place-items-center rounded-full font-serif text-[22px] text-value shadow-[inset_0_0_0_1px_var(--hairline-6)] [background:linear-gradient(150deg,#2a2622,#191518)]">
          {initials}
        </div>
        <div className="min-w-0 flex-1">
          <h1 className="font-serif text-[25px]/[1] text-foreground">{name}</h1>
          <p className="mt-[5px] text-[13px] text-muted-foreground">{handle}</p>
        </div>
      </div>

      {/* The closet cap is deliberately absent. Same reasoning as the reroll
          meter: a visible allowance makes a free user think about the limit
          constantly, and 50 is far enough out that most never approach it. */}
      <div
        data-testid="stat-trio"
        className="mt-[22px] flex overflow-hidden rounded-[14px] bg-surface-1 shadow-[inset_0_0_0_1px_var(--hairline-2)]"
      >
        <StatCell value={String(stats.pieces)} label="Pieces" />
        <StatCell value={String(stats.outfits)} label="Outfits worn" />
        <StatCell value={String(stats.streak)} label="Day streak" />
      </div>

      <Link
        href="/style-dna"
        className="relative mt-[13px] block overflow-hidden rounded-[16px] p-5 shadow-[inset_0_0_0_1px_rgba(184,106,71,0.18)] [background:radial-gradient(120%_120%_at_82%_8%,#241d18,#161517)]"
      >
        <span className="text-[10px] uppercase tracking-[0.22em] text-[#b89a6a]">Your archetype</span>
        <div className="mt-[6px] font-serif text-[30px] text-foreground">
          {archetype ?? "Not set yet"}
        </div>
        <div className="mt-[14px] flex gap-[5px]">
          {palette.map((c) => (
            <div
              key={c}
              className="size-[30px] rounded-[7px] shadow-[inset_0_0_0_1px_rgba(255,255,255,0.07)]"
              style={{ background: c }}
            />
          ))}
        </div>
        <span className="absolute right-[18px] top-6 text-[20px] text-muted-dim" aria-hidden="true">
          ›
        </span>
      </Link>

      <div className="mt-[13px] flex flex-col gap-[10px]">
        {links.map((l) => (
          <LinkRow key={l.label} link={l} />
        ))}
      </div>

      {/* Inert by design: there is no checkout, and a button that goes nowhere
          is worse than none. This card is the explanation, not the purchase. */}
      <div
        data-testid="pro-card"
        className="mt-[13px] rounded-[16px] p-5 [background:linear-gradient(120deg,#b86a47,#9a5236)]"
      >
        <div className="font-serif text-[21px] italic text-[#1a0f09]">Fitcheck Pro</div>

        {isPro ? (
          <>
            <p className="mt-[5px] text-[13px]/[1.4] text-[rgba(26,15,9,0.82)]">
              Active — everything below is yours.
            </p>
            <ul className="mt-3 flex flex-col gap-[6px]">
              {PRO_BENEFITS.map((b) => (
                <li key={b} className="text-[13px]/[1.35] text-[rgba(26,15,9,0.82)]">
                  {b}
                </li>
              ))}
            </ul>
          </>
        ) : (
          <>
            {/* The design's pitch, verbatim — it names packing mode, which does
                not exist yet. Deliberate while nothing can be bought; it must be
                built before Pro is actually sold. */}
            <p className="mt-[5px] max-w-[84%] text-[13px]/[1.4] text-[rgba(26,15,9,0.82)]">
              Unlimited daily looks, packing mode &amp; cost-per-wear analytics.
            </p>
            <ul className="mt-3 flex flex-col gap-[6px]">
              {PRO_BENEFITS.map((b) => (
                <li key={b} className="text-[13px]/[1.35] text-[rgba(26,15,9,0.82)]">
                  {b}
                </li>
              ))}
            </ul>
            <div className="mt-[13px] inline-block rounded-full bg-canvas px-[17px] py-[9px] text-[13px] font-semibold text-foreground">
              Go Pro · €5/mo
            </div>
          </>
        )}
      </div>

      {children && <div className="mt-[13px]">{children}</div>}
    </div>
  );
}

